#include "political_subordinate_appointment_decisions.hpp"
#include "political_subordinate_appointment_detail.hpp"
namespace hanmo::resident {
Outcome<PoliticalSubordinateAppointmentChoice> propose_political_subordinate_appointment(const PoliticalSubordinateAppointmentContext& x,const PoliticalNavigationRead& navigation,const StableId& actor,const StableId& selected,Integer budget){using namespace subordinate_appointment_detail;PoliticalSubordinateAppointmentChoice out;const auto fail=[&](const RuleError& e){return Outcome<PoliticalSubordinateAppointmentChoice>{false,{},e};};
 if(!x.intents||!x.career||budget<1||budget>64)return fail(common_failure("PoliticalSubordinateIntentProfileRequired").error);if(actor==x.common.state().metadata.player_actor_id){out.reason="PlayerControlled";return {true,out,{}};}auto ready=politics_detail::available(x.common,x.activity,actor);if(!ready.ok){out.reason=ready.error.original.code;return {true,out,{}};}if(x.activity.in_interaction(actor)){out.reason="InteractionBusy";return {true,out,{}};}
 auto catalog=validate_political_subordinate_appointment_intents(*x.intents,x.common_catalog,x.politics_catalog,x.organization_catalog,x.heads,x.catalog,x.career);if(!catalog.ok)return fail(catalog.error);
 const auto route=[&](const StableId& target,Integer cost)->Status{out.target_place_id=target;auto step=next_travel_command(x.common,navigation.state,navigation.catalog,navigation.services,actor,target);if(!step.ok)return {false,{},step.error};if(!step.value.command)return common_failure("PoliticalSubordinateNavigationLocationMismatch",actor,ErrorKind::internal);if(std::holds_alternative<TravelCommand>(*step.value.command)&&!step.value.travel_quote)return common_failure("PoliticalSubordinateTravelQuoteRequired",actor,ErrorKind::internal);if(step.value.travel_quote&&step.value.travel_quote->cost>cost)return common_failure("PoliticalTravelQuoteLimitExceeded",actor);out.travel=std::move(step.value);out.reason="PoliticalSubordinateTravelRequired";return common_success();};
 const auto proposed=[&](AuthoredSubordinateAppointmentCommand command)->Status{auto rules=x;rules.authored=&command.origin;auto q=preview_political_subordinate_appointment(rules,actor,command.command);if(!q.ok)return {false,{},q.error};out.command=std::move(command);out.reason="PoliticalSubordinateBusinessReady";return common_success();};
 // 本人真正收到的任官与本人已答受赴任优先于尚未提出的新staffing机会。
 for(int pass=0;pass<2;++pass)for(const auto& row:x.intents->intents.rows()){const auto& i=row.second;const bool candidate=actor==i.candidate_actor_id&&selected==i.candidate_director_policy_id;const bool issuer=actor==i.issuer_actor_id&&selected==i.issuer_director_policy_id;if((pass==0&&!candidate)||(pass==1&&!issuer))continue;if(out.inspected>=budget){out.reason="PoliticalDecisionBudgetReached";return {true,out,{}};}++out.inspected;const auto& p=*x.catalog.policies.find(i.appointment_policy_id);const auto& h=*x.heads.policies.find(p.head_succession_policy_id);const auto& j=*x.politics_catalog.jurisdictions.find(p.jurisdiction_id);const auto* career=x.career(selected);if(!career)return fail(common_failure("PoliticalSubordinateCareerPolicyRequired",selected).error);const auto* person=x.common.actor(actor);const auto* local=person?std::get_if<SettlementLocation>(&person->location):nullptr;
  const PoliticalSubordinateAppointmentOffer* known=nullptr;for(const auto& offered:x.state.offers.rows()){const auto& o=offered.second;if(o.policy_id==p.id&&o.issuer_actor_id==i.issuer_actor_id&&o.candidate_actor_id==i.candidate_actor_id)known=&o;}
  out.intent_id=i.id;
  if(candidate){if(!known)continue;out.source_fact_id=known->id;const auto* answered=answer(x.state,known->id);if(answered){out.source_fact_id=answered->id;if(!answered->accepted){out.completed=true;out.reason="PoliticalSubordinateDeclined";return {true,out,{}};}if(const auto* installed=arrival(x.state,known->id)){out.source_fact_id=installed->id;out.completed=true;out.reason="PoliticalSubordinateArrived";return {true,out,{}};}if(x.common.tick()>=answered->arrival_until){out.reason="PoliticalSubordinateAppointmentClosed";return {true,out,{}};}}
   else if(x.common.tick()>=known->response_until){out.reason="PoliticalSubordinateAppointmentClosed";return {true,out,{}};}
   const StableId target=answered?j.seat_place_id:h.seat_place_id;
   // 远方不扫描撤回/今日首长/他人的健康与岗位；只沿本人的实际原接受和不可变目标报价。
   if(!local||local->place_id!=target){auto move=route(target,career->maximum_travel_quote_cost);if(!move.ok){if(move.error.kind!=ErrorKind::rule)return fail(move.error);out.reason=move.error.original.code;}return {true,out,{}};}
   PoliticalSubordinateAppointmentAuthoredOrigin origin{i.id,selected,actor,known->id,answered?"arrival":"answer"};PoliticalSubordinateAppointmentCommand command;
   if(answered)command=PoliticalArriveSubordinateAppointment{answered->id,known->target_epoch};else{auto response=read_political_subordinate_career_response(*career,known->organization_id,j.id);if(!response.ok){out.reason=response.error.original.code;return {true,out,{}};}command=PoliticalAnswerSubordinateAppointment{known->id,response.value};}
   auto action=proposed({origin,command});if(!action.ok){if(action.error.kind!=ErrorKind::rule)return fail(action.error);out.reason=action.error.original.code;}return {true,out,{}};
  }
  // 首长已有这份提名时不因远方候选今日状态自动重开；新空职须当地重核真实epoch。
  if(known){out.source_fact_id=known->id;if(!local||local->place_id!=h.seat_place_id){out.completed=true;out.reason="PoliticalSubordinateOfferIssued";return {true,out,{}};}const auto* target=x.organizations.offices.find(j.office_id);if(!target||target->epoch==known->target_epoch){out.completed=true;out.reason="PoliticalSubordinateOfferIssued";return {true,out,{}};}}
  if(!local||local->place_id!=h.seat_place_id){auto move=route(h.seat_place_id,career->maximum_travel_quote_cost);if(!move.ok){if(move.error.kind!=ErrorKind::rule)return fail(move.error);out.reason=move.error.original.code;}return {true,out,{}};}
  const auto* original=x.organizations.offices.find(h.leader_office_id);const auto* vacancy=x.organizations.offices.find(j.office_id);if(!original||!vacancy)return fail(common_failure("PoliticalSubordinateOriginalOfficeRequired",p.id).error);AuthoredSubordinateAppointmentCommand command{{i.id,selected,actor,{},"offer"},PoliticalOfferSubordinateAppointment{{h.organization_id,h.leader_office_id,original->epoch,actor},p.id,i.candidate_actor_id,vacancy->epoch,0}};auto action=proposed(std::move(command));if(action.ok)return {true,out,{}};if(action.error.kind!=ErrorKind::rule)return fail(action.error);out.reason=action.error.original.code;
 }
 if(out.reason.empty())out.reason="NoPoliticalSubordinateOpportunity";return {true,out,{}};
}
}
